<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'; import SearchInput from '@/components/molecules/SearchInput.vue'; import EmptyState from '@/components/molecules/EmptyState.vue'; import AppSpinner from '@/components/atoms/AppSpinner.vue'; import AppBadge from '@/components/atoms/AppBadge.vue'; import {useMouvementStore} from '@/stores/mouvement'
const store=useMouvementStore();const search=ref('');const movementId=ref('');const movements=computed(()=>store.dashboard?.movements??(store.movement?[store.movement]:[]));const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return !q?store.parents:store.parents.filter(p=>`${p.firstName} ${p.lastName}`.toLowerCase().includes(q)||(p.phone??'').includes(q)||(p.email??'').toLowerCase().includes(q))});async function load(){await store.loadParents(movementId.value?{movementId:movementId.value}:undefined)};onMounted(async()=>{await Promise.all([store.loadDashboard(),store.loadParents()])});watch(movementId,load)
</script>
<template><section class="space-y-6"><header class="border-b border-[#C2BAB0] pb-5"><p class="eyebrow text-[#C25A34]">Gestion du mouvement</p><h1 class="page-title mt-1 text-4xl text-[#0B1F3A]">Parents</h1><p class="mt-2 text-[#6B655D]">Retrouvez les parents associés aux enfants de vos mouvements.</p></header><div class="grid gap-3 md:grid-cols-[minmax(0,1fr)_240px]"><SearchInput v-model="search" placeholder="Nom, téléphone ou e-mail…" /><select v-model="movementId" class="min-h-10 border border-[#C2BAB0] bg-white px-3 text-sm"><option value="">Tous mes mouvements</option><option v-for="m in movements" :key="m.id" :value="m.id">{{m.name}}</option></select></div><div v-if="store.loading" class="flex min-h-40 items-center justify-center"><AppSpinner/></div><div v-else-if="filtered.length" class="overflow-hidden border border-[#C2BAB0] bg-white"><div class="hidden overflow-x-auto md:block"><table class="w-full text-left text-sm"><thead class="bg-[#F7F5F2] text-xs uppercase tracking-wide text-[#6B655D]"><tr><th class="px-5 py-4">Parent</th><th class="px-5 py-4">Téléphone</th><th class="px-5 py-4">E-mail</th><th class="px-5 py-4">Statut</th></tr></thead><tbody><tr v-for="p in filtered" :key="p.id" class="border-t border-[#EDE9E4]"><td class="px-5 py-4 font-semibold">{{p.firstName}} {{p.lastName}}</td><td class="px-5 py-4">{{p.phone||'—'}}</td><td class="px-5 py-4 text-[#6B655D]">{{p.email||'—'}}</td><td class="px-5 py-4"><AppBadge tone="success">Actif</AppBadge></td></tr></tbody></table></div><div class="divide-y divide-[#EDE9E4] md:hidden"><article v-for="p in filtered" :key="p.id" class="p-5"><div class="flex items-center justify-between gap-3"><p class="font-semibold text-[#14345E]">{{p.firstName}} {{p.lastName}}</p><AppBadge tone="success">Actif</AppBadge></div><p class="mt-3 text-sm">{{p.phone||'Téléphone non renseigné'}}</p><p class="text-sm text-[#6B655D]">{{p.email||'E-mail non renseigné'}}</p></article></div></div><EmptyState v-else title="Aucun parent trouvé" description="Aucun parent ne correspond à la recherche actuelle."/></section></template>